    if(!r.rowCount)return res.status(404).json({message:'Dealer order not found'});
    const o=r.rows[0];if(o.sales_invoice_id)return res.status(409).json({message:'A sales invoice is already linked to this dealer order'});if(o.status!=='READY_TO_DISPATCH'||!o.stock_confirmed_at||!o.payment_terms_confirmed_at)return res.status(409).json({message:'Move the order to Ready to Dispatch and confirm stock and payment terms before creating its sales invoice'});if(!o.customer_id)return res.status(409).json({message:'Link this dealer to an active customer ledger account before invoicing'});
    const lines=Array.isArray(o.items_snapshot)?o.items_snapshot:[];if(!lines.length)return res.status(409).json({message:'The accepted quotation has no invoiceable items'});
