    const invoice=await loadInvoice(req.params.id,c);if(!await permitted(req,res,invoice.store_id)){await c.query('ROLLBACK');return;}if(invoice.status!=='posted')throw Object.assign(new Error('Only posted invoices can use the revision workflow'),{status:409});
