export async function cancellationPreview(req,res){
  if(!idOk(req.params.id))return res.status(400).json({message:'Invalid invoice ID'});
  try{const inv=await connection.query(`SELECT si.id,si.store_id,si.status,si.invoice_number,si.invoice_date,si.total,si.customer_id,si.document_type,si.dealer_order_id,c.name customer_name FROM sales_invoices si LEFT JOIN customers c ON c.id=si.customer_id WHERE si.id=$1`,[req.params.id]);if(!inv.rowCount)return res.status(404).json({message:'Invoice not found'});const i=inv.rows[0];if(!await permitted(req,res,i.store_id))return;
    const payments=await connection.query(`SELECT p.id,p.payment_number receipt_number,p.payment_date,p.payment_method,p.reference,p.status verification_status,pa.amount-COALESCE(ar.amount,0) allocated_amount FROM payment_allocations pa JOIN payments p ON p.id=pa.payment_id LEFT JOIN LATERAL(SELECT sum(amount) amount FROM payment_allocation_reversals WHERE allocation_id=pa.id) ar ON TRUE WHERE pa.sales_invoice_id=$1 AND pa.direction='in' AND p.status='posted' AND pa.amount>COALESCE(ar.amount,0) ORDER BY p.payment_date,p.id`,[i.id]);
    const lines=await connection.query(`SELECT li.product_name_snapshot product_name,li.quantity,li.unit_name_snapshot unit_name,sm.id movement_id,sm.quantity_delta,EXISTS(SELECT 1 FROM stock_movements rev WHERE rev.reversal_of_id=sm.id) already_reversed FROM sales_invoice_items li LEFT JOIN stock_movements sm ON sm.source_type='sales_invoice' AND sm.source_id=li.sales_invoice_id AND sm.source_line_id=li.id AND sm.movement_type='sale' WHERE li.sales_invoice_id=$1 ORDER BY li.line_number`,[i.id]);
    const bonus=await connection.query(`SELECT COALESCE(sum(br.final_user_bonus+COALESCE(adj.amount,0)),0)::numeric(18,2) entitlement,COALESCE(sum(br.total_amount_paid),0)::numeric(18,2) paid FROM sales_bonus_records br LEFT JOIN LATERAL(SELECT sum(amount) amount FROM sales_bonus_adjustments WHERE sales_bonus_record_id=br.id) adj ON TRUE WHERE br.source_sales_invoice_id=$1`,[i.id]);
    const allocated=payments.rows.reduce((s,p)=>s+Number(p.allocated_amount),0);return res.json({...i,amount_paid:allocated,outstanding_balance:Math.max(0,Number(i.total)-allocated),payments:payments.rows,inventory_impact:lines.rows,bonus_impact:bonus.rows[0],cancellation_blocked:i.status!=='posted'?'Only finalized invoices can use this workflow':null});
  }catch(e){return dbError(res,e,'Unable to load cancellation preview');}
}
export async function cancelFinalizedSales(req,res){
  if(!idOk(req.params.id))return res.status(400).json({message:'Invalid invoice ID'});
  const reason=String(req.body?.reason||'').trim().toUpperCase(),remarks=String(req.body?.remarks||'').trim(),dup=req.body?.duplicateOfInvoiceId||null,allocations=req.body?.settlement?.allocations||[];
  if(!['DUPLICATE_INVOICE','WRONG_CUSTOMER','WRONG_PRODUCT','INCORRECT_BILLING','ORDER_CANCELLED','OTHER'].includes(reason))return res.status(400).json({message:'Choose a valid cancellation reason'});
  if(remarks.length>2000||!Array.isArray(allocations)||allocations.length>100)return res.status(400).json({message:'Invalid cancellation details'});
  const c=await connection.connect();try{await c.query('BEGIN');const lock=await c.query('SELECT * FROM sales_invoices WHERE id=$1 FOR UPDATE',[req.params.id]);if(!lock.rowCount)throw Object.assign(new Error('Invoice not found'),{status:404});const inv=lock.rows[0];if(!await canAccessStore(req.user,inv.store_id)){await c.query('ROLLBACK');return res.status(403).json({message:'You do not have access to this store'});}if(!isAdmin(req))throw Object.assign(new Error('Only an Admin can cancel a finalized invoice'),{status:403});if(inv.status!=='posted')throw Object.assign(new Error('Only active finalized invoices can be cancelled'),{status:409});
    if(inv.document_type==='GST_TAX_INVOICE')throw Object.assign(new Error('GST tax invoices require review of reporting and e-invoice status. Use the controlled tax correction workflow.'),{status:409,code:'TAX_REVIEW_REQUIRED'});
    if(inv.dealer_order_id){const delivery=await c.query("SELECT status FROM dealer_orders WHERE id=$1 FOR UPDATE",[inv.dealer_order_id]);if(delivery.rowCount&&['SHIPPED','DELIVERED'].includes(delivery.rows[0].status))throw Object.assign(new Error('This dealer order has shipped or been delivered. Reconcile fulfillment and physical stock before invoice cancellation.'),{status:409,code:'FULFILLMENT_REVIEW_REQUIRED'});}
    const exposure=await c.query(`SELECT EXISTS(SELECT 1 FROM sales_returns WHERE sales_invoice_id=$1 AND status IN ('posted','draft')) OR EXISTS(SELECT 1 FROM sales_return_items ri JOIN sales_returns r ON r.id=ri.sales_return_id JOIN sales_invoice_items li ON li.id=ri.sales_invoice_item_id WHERE li.sales_invoice_id=$1 AND r.status IN ('posted','draft')) OR EXISTS(SELECT 1 FROM sales_invoice_return_credits WHERE sales_invoice_id=$1 AND status='posted') AS has_returns`,[inv.id]);if(exposure.rows[0].has_returns)throw Object.assign(new Error('This invoice has a return or credit history. Review the correction chain before cancellation.'),{status:409,code:'RETURN_REVIEW_REQUIRED'});
    if(reason==='DUPLICATE_INVOICE'&&!idOk(dup))throw Object.assign(new Error('Choose the original invoice for a duplicate cancellation'),{status:400});
    const targetById=new Map();for(const x of allocations){if(!idOk(x.paymentId)||!idOk(x.targetInvoiceId)||!/^\d+(\.\d{1,2})?$/.test(String(x.amount))||Number(x.amount)<=0)throw Object.assign(new Error('Payment allocation details are invalid'),{status:400});}
    if(dup){const original=await c.query("SELECT id FROM sales_invoices WHERE id=$1 AND customer_id IS NOT DISTINCT FROM $2 AND store_id=$3 AND status='posted' FOR UPDATE",[dup,inv.customer_id,inv.store_id]);if(!original.rowCount||String(dup)===String(inv.id))throw Object.assign(new Error('The original invoice must be active and belong to the same customer and store'),{status:409});}
    const linked=await c.query(`SELECT pa.id allocation_id,pa.payment_id,pa.amount-COALESCE(ar.amount,0) amount,p.amount payment_amount,p.payment_number FROM payment_allocations pa JOIN payments p ON p.id=pa.payment_id LEFT JOIN LATERAL(SELECT sum(amount) amount FROM payment_allocation_reversals WHERE allocation_id=pa.id) ar ON TRUE WHERE pa.sales_invoice_id=$1 AND pa.direction='in' AND p.status='posted' AND pa.amount>COALESCE(ar.amount,0) ORDER BY pa.id FOR UPDATE OF pa,p`,[inv.id]);
    const allocationTotal=linked.rows.reduce((s,x)=>s+Number(x.amount),0),requestedByPayment=new Map();for(const x of allocations)requestedByPayment.set(String(x.paymentId),(requestedByPayment.get(String(x.paymentId))||0)+Number(x.amount));
    for(const [paymentId,amount] of requestedByPayment){const source=linked.rows.filter(x=>String(x.payment_id)===paymentId);if(!source.length)throw Object.assign(new Error('A selected receipt is not allocated to this invoice'),{status:409});const p=await c.query('SELECT * FROM payments WHERE id=$1 FOR UPDATE',[paymentId]);if(!p.rowCount||p.rows[0].status!=='posted'||String(p.rows[0].customer_id||'')!==String(inv.customer_id||'')||String(p.rows[0].store_id)!==String(inv.store_id))throw Object.assign(new Error('Receipt is not verified for this customer and store'),{status:409});const totalSource=source.reduce((s,x)=>s+Number(x.amount),0);if(amount>totalSource)throw Object.assign(new Error('Reallocation exceeds the amount available on the selected receipt'),{status:409});for(const x of allocations.filter(a=>String(a.paymentId)===paymentId)){const t=await c.query("SELECT id,total FROM sales_invoices WHERE id=$1 AND status='posted' AND customer_id IS NOT DISTINCT FROM $2 AND store_id=$3 FOR UPDATE",[x.targetInvoiceId,inv.customer_id,inv.store_id]);if(!t.rowCount||String(x.targetInvoiceId)===String(inv.id))throw Object.assign(new Error('Target invoice must be active and belong to the same customer and store'),{status:409});targetById.set(String(x.targetInvoiceId),t.rows[0]);}}
    for(const row of linked.rows)await c.query('INSERT INTO payment_allocation_reversals(allocation_id,amount,reason,created_by) VALUES($1,$2,$3,$4)',[row.allocation_id,row.amount,`Invoice cancellation ${inv.invoice_number}`,req.user.id]);
    for(const x of allocations)await c.query("INSERT INTO payment_allocations(payment_id,store_id,direction,sales_invoice_id,amount) VALUES($1,$2,'in',$3,$4)",[x.paymentId,inv.store_id,x.targetInvoiceId,x.amount]);
    for(const [targetId,target] of targetById){const paid=await c.query(`SELECT COALESCE(sum(a.amount-COALESCE(r.amount,0)),0)::numeric(18,2) amount FROM payment_allocations a JOIN payments p ON p.id=a.payment_id AND p.status='posted' LEFT JOIN LATERAL(SELECT sum(amount) amount FROM payment_allocation_reversals WHERE allocation_id=a.id) r ON TRUE WHERE a.sales_invoice_id=$1 AND a.direction='in'`,[targetId]);const newly=requestedByPayment.size?allocations.filter(x=>String(x.targetInvoiceId)===targetId).reduce((s,x)=>s+Number(x.amount),0):0;if(Number(paid.rows[0].amount)+newly>Number(target.total))throw Object.assign(new Error('Reallocation exceeds the target invoice outstanding balance'),{status:409});}
    const moves=await c.query(`SELECT sm.* FROM stock_movements sm WHERE (sm.source_type='sales_invoice' AND sm.source_id=$1 AND sm.movement_type='sale') OR (sm.source_type='sales_invoice_revision' AND sm.movement_type='adjustment' AND sm.source_id IN(SELECT id FROM sales_invoice_revisions WHERE invoice_id=$1)) ORDER BY sm.id FOR UPDATE`,[inv.id]);for(const m of moves.rows){const existing=await c.query("SELECT 1 FROM stock_movements WHERE reversal_of_id=$1",[m.id]);if(existing.rowCount)continue;await c.query("INSERT INTO stock_movements(store_id,product_id,movement_type,quantity_delta,source_type,source_id,source_line_id,reversal_of_id,idempotency_key,created_by) VALUES($1,$2,'reversal',$3,'sales_invoice_cancel',$4,$5,$6,$7,$8)",[m.store_id,m.product_id,-m.quantity_delta,inv.id,m.source_line_id,m.id,`invoice-cancel:${inv.id}:${m.id}`,req.user.id]);}
    await reverseInvoiceBonus(c,inv.id,req.user.id,inv.store_id);
    await c.query("UPDATE sales_invoices SET status='cancelled',cancellation_reason=$2,cancellation_date=COALESCE($3::date,current_date),cancelled_by=$4,duplicate_of_invoice_id=$5,cancellation_remarks=$6,updated_at=now() WHERE id=$1",[inv.id,reason,req.body?.cancellationDate||null,req.user.id,dup,remarks||null]);
    await c.query('INSERT INTO sales_invoice_cancellation_events(sales_invoice_id,store_id,reason,cancellation_date,duplicate_of_invoice_id,remarks,allocation_settlement,created_by) VALUES($1,$2,$3,COALESCE($4::date,current_date),$5,$6,$7,$8)',[inv.id,inv.store_id,reason,req.body?.cancellationDate||null,dup,remarks||null,allocations,req.user.id]);
    await c.query("INSERT INTO audit_logs(store_id,user_id,action,entity_type,entity_id,before_data,after_data) VALUES($1,$2,'sales.invoice.cancelled','sales_invoice',$3,$4,$5)",[inv.store_id,req.user.id,inv.id,{status:inv.status,invoiceNumber:inv.invoice_number},{status:'cancelled',reason,duplicateOfInvoiceId:dup,allocationSettlement:allocations}]);
    await c.query('COMMIT');return res.json(await loadInvoice(inv.id));
  }catch(e){await c.query('ROLLBACK').catch(()=>{});return dbError(res,e,'Unable to cancel invoice');}finally{c.release();}
}
export async function salesBonusPreview(req,res){
  const storeId=String(req.body?.storeId||''),referralId=req.body?.referredByUserId;
  if(!idOk(storeId)||!Array.isArray(req.body?.items)||req.body.items.length>100)return res.status(400).json({message:'Choose a store and provide valid invoice lines'});
  if(!await permitted(req,res,storeId))return;
  const discount=decimal(req.body.invoiceDiscount??'0','Invoice discount',{scale:2});if(discount.includes(' must be a valid '))return res.status(400).json({message:discount});
  if(referralId&&!idOk(referralId))return res.status(400).json({message:'Choose a valid referral'});
  const items=[];for(const [index,line] of req.body.items.entries()){
    if(!idOk(line.productId)||!idOk(line.unitId))return res.status(400).json({message:`Line ${index+1}: choose a valid product and unit`});
    const quantity=decimal(line.quantity,'Quantity'),unitPrice=decimal(line.unitPrice,'Selling price',{scale:4}),discountAmount=decimal(line.discountAmount??'0','Discount',{scale:2});
    if([quantity,unitPrice,discountAmount].some(value=>value.includes(' must be a valid '))||Number(quantity)<=0)return res.status(400).json({message:`Line ${index+1}: enter a valid quantity, selling price, and discount`});
    items.push({productId:String(line.productId),unitId:String(line.unitId),quantity,unitPrice,discountAmount});
  }
  try{const quote=await quoteSalesInvoiceBonus(connection,{referredByUserId:referralId,items,invoiceDiscount:Number(discount)});const showFinancials=hasPermission(req.user,'bonus_cost.view');return res.json({...quote,items:quote.items.map(item=>showFinancials?item:{productName:item.productName,quantity:item.quantity,sellingPrice:item.sellingPrice,bonusRate:item.bonusRate,bonus:item.bonus}),totals:quote.totals?(showFinancials?quote.totals:{userBonus:quote.totals.userBonus}):null});}
  catch(e){console.error('Unable to calculate sales bonus preview:',e.message);return res.status(500).json({message:'Unable to calculate sales bonus preview'});}
}
export async function updateSalesDraft(req,res){
  const v=validate(req.body);if(v.error)return res.status(400).json({message:v.error,...(v.code?{code:v.code,field:v.field}:{})});const d=v.data;const c=await connection.connect();try{await c.query("BEGIN");const r=await c.query("SELECT store_id,status,invoice_type,invoice_layout,document_type,place_of_supply_state,dealer_order_id FROM sales_invoices WHERE id=$1 FOR UPDATE",[req.params.id]);if(!r.rowCount)throw Object.assign(new Error("Invoice not found"),{status:404});if(!await permitted(req,res,r.rows[0].store_id)){await c.query("ROLLBACK");return;}if(r.rows[0].status!=="draft")throw Object.assign(new Error("Only draft invoices can be edited"),{status:409});if(String(r.rows[0].store_id)!==d.storeId)throw Object.assign(new Error("The store cannot be changed"),{status:400});
  if(r.rows[0].dealer_order_id){const linked=await c.query("SELECT transport_charge FROM dealer_orders WHERE id=$1 AND sales_invoice_id=$2 FOR UPDATE",[r.rows[0].dealer_order_id,req.params.id]);if(!linked.rowCount)throw Object.assign(new Error("Dealer order invoice link is inconsistent"),{status:409});d.dealerOrder=true;d.additionalCharges=String(linked.rows[0].transport_charge||"0");}
  d.invoiceType=r.rows[0].invoice_type;d.documentType=r.rows[0].document_type;d.invoiceLayout=r.rows[0].invoice_layout;
  if(req.body.documentType&&req.body.documentType!==d.documentType || req.body.invoiceLayout&&req.body.invoiceLayout!==d.invoiceLayout)throw Object.assign(new Error('Invoice document type and appearance cannot be converted; create a replacement draft'),{status:409});
  if(req.body.invoiceType && req.body.invoiceType!==d.invoiceType)throw Object.assign(new Error("Invoice type cannot be converted; create a new draft"),{status:409});
  if(d.referredByUserId){const x=await c.query("SELECT id,name FROM users WHERE id=$1 AND is_active=TRUE AND user_type IN ('Salesperson','Tile Mistire')",[d.referredByUserId]);if(!x.rowCount)throw Object.assign(new Error("Choose an active salesperson or tile mistiri"),{status:400});d.referredByName=x.rows[0].name;}
  await c.query("UPDATE sales_invoices SET customer_id=$2,referred_by_user_id=$3,referred_by_name_snapshot=$4,invoice_date=$5,due_date=$6,notes=$7,place_of_supply_state=$8,vehicle_number=$9,driver_name=$10,driver_contact_number=$11,transport_mode_snapshot=CASE WHEN dealer_order_id IS NULL THEN $12 ELSE transport_mode_snapshot END WHERE id=$1",[req.params.id,d.customerId,d.referredByUserId,d.referredByName||null,d.date,d.due,d.notes,d.placeOfSupply,d.vehicleNumber,d.driverName,d.driverContactNumber,d.transportMode]);await saveItems(c,req.params.id,d);await c.query("COMMIT");return res.json(await loadInvoice(req.params.id));
  }catch(e){await c.query("ROLLBACK").catch(()=>{});return dbError(res,e,"Unable to update sales draft");}finally{c.release();}
}
async function validateInitialPayment(client,payment,amount,method,total){
  const invalid=message=>Object.assign(new Error(message),{status:400,code:'INVALID_PAYMENT_AMOUNT',field:'payment.amount',invoiceTotal:total});
  const exceeds=await client.query('SELECT $1::numeric>$2::numeric AS yes',[amount,total]);
  if(exceeds.rows[0].yes)throw invalid('Received amount cannot exceed the invoice total. Record customer advances through the separate receipts workflow.');
  if(Number(amount)===0)return;
  const key=String(payment?.idempotencyKey||'');
  if(key.length<8||key.length>120)throw Object.assign(new Error('A payment idempotency key is required'),{status:400,code:'INVALID_PAYMENT_KEY',field:'payment.idempotencyKey'});
  const configured=await client.query('SELECT 1 FROM payment_method_options WHERE code=$1 AND is_active=TRUE',[method]);
  if(!configured.rowCount)throw Object.assign(new Error('Payment method is not configured or active'),{status:400,code:'INVALID_PAYMENT_METHOD',field:'payment.method'});
}

export async function finalizeSales(req,res){
  const id=req.params.id;if(!idOk(id))return res.status(400).json({message:"Invalid invoice ID"});const amount=decimal(req.body?.payment?.amount??"0","Payment amount",{scale:2});if(amount.includes(" must be a valid "))return res.status(400).json({code:"INVALID_PAYMENT_AMOUNT",field:"payment.amount",message:amount});const method=req.body?.payment?.method||"cash";
  if(Number(amount)>0&&!hasPermission(req.user,'payments.manage'))return res.status(403).json({code:'PERMISSION_DENIED',message:'Payment management permission is required to receive payment. Finalize without an initial payment or ask your administrator.'});
  const c=await connection.connect();try{await c.query("BEGIN");const r=await c.query(`SELECT si.*,si.invoice_date::text AS invoice_date,s.invoice_numbering_period,s.invoice_number_padding,s.code FROM sales_invoices si JOIN stores s ON s.id=si.store_id WHERE si.id=$1 FOR UPDATE OF si`,[id]);if(!r.rowCount)throw Object.assign(new Error("Invoice not found"),{status:404});const inv=r.rows[0];if(!await permitted(req,res,inv.store_id)){await c.query("ROLLBACK");return;}if(inv.status!=="draft")throw Object.assign(new Error("Only a draft invoice can be finalized"),{status:409,code:"INVOICE_ALREADY_FINALIZED"});let dealerOrder=null;if(inv.dealer_order_id){const linked=await c.query(`SELECT o.* FROM dealer_orders o WHERE o.id=$1 AND o.sales_invoice_id=$2 FOR UPDATE`,[inv.dealer_order_id,inv.id]);if(!linked.rowCount)throw Object.assign(new Error('Dealer order invoice link is inconsistent'),{status:409});dealerOrder=linked.rows[0];if(dealerOrder.status!=='READY_TO_DISPATCH'||!dealerOrder.stock_confirmed_at||!dealerOrder.payment_terms_confirmed_at)throw Object.assign(new Error('Dealer order must be ready to dispatch before invoice finalization'),{status:409});}
    if(inv.customer_id){const customer=await c.query('SELECT id FROM customers WHERE id=$1 AND is_active=TRUE FOR SHARE',[inv.customer_id]);if(!customer.rowCount)throw Object.assign(new Error('Active customer not found'),{status:422,code:'INVALID_CUSTOMER',field:'customerId'});}
    if(inv.document_type){
      const settings=await checkDocument(c,{storeId:inv.store_id,documentType:inv.document_type,placeOfSupply:inv.place_of_supply_state});
      if(inv.document_type==='BILL_OF_SUPPLY'&&settings.gst_registration_category!==inv.registration_category_snapshot)throw Object.assign(new Error('Registration category changed since drafting. Create a replacement draft.'),{status:409,code:'DOCUMENT_NOT_ELIGIBLE',field:'documentType'});
      // Revalidate/recalculate from the saved draft and current authorized catalog, never request totals.
      const saved=await c.query('SELECT product_id,unit_id,quantity,unit_price,discount_amount,tax_rate FROM sales_invoice_items WHERE sales_invoice_id=$1 ORDER BY line_number',[id]);
      await saveItems(c,id,{storeId:inv.store_id,customerId:inv.customer_id,documentType:inv.document_type,invoiceType:inv.invoice_type,invoiceLayout:inv.invoice_layout,placeOfSupply:inv.place_of_supply_state,
        invoiceDiscount:inv.invoice_discount,additionalCharges:inv.additional_charges,roundOff:inv.round_off,dealerOrder:Boolean(dealerOrder),
        items:saved.rows.map(x=>({productId:x.product_id,unitId:x.unit_id,quantity:x.quantity,unitPrice:x.unit_price,discountAmount:x.discount_amount,taxRate:x.tax_rate}))});
      inv.total=(await c.query('SELECT total FROM sales_invoices WHERE id=$1',[id])).rows[0].total;
    }else if(inv.invoice_type==="NON_GST") {
      const settings=await readInvoiceSettings(c,inv.store_id,true);
      if(!settings)throw Object.assign(new Error("Active store not found"),{status:404});
    }
    if(dealerOrder){const matched=await c.query('SELECT $1::numeric=$2::numeric AS yes',[inv.total,dealerOrder.grand_total]);if(!matched.rows[0].yes)throw Object.assign(new Error('Final invoice totals no longer match the dealer-accepted quotation. Revise and reaccept the quotation before posting.'),{status:409,code:'DEALER_QUOTATION_TOTAL_CHANGED'});}
    await validateInitialPayment(c,req.body?.payment,amount,method,inv.total);
    const lines=await c.query(`SELECT li.id,li.product_id,li.quantity,li.unit_id,CASE WHEN p.base_unit_id=li.unit_id THEN 1::numeric ELSE conv.factor_to_base END AS factor
      FROM sales_invoice_items li JOIN products p ON p.id=li.product_id LEFT JOIN product_unit_conversions conv ON conv.product_id=p.id AND conv.unit_id=li.unit_id
      WHERE li.sales_invoice_id=$1 ORDER BY li.product_id,li.id`,[id]);if(!lines.rowCount)throw Object.assign(new Error("Invoice requires at least one item"),{status:400});
    if(lines.rows.some(line=>line.factor===null))throw Object.assign(new Error("A product unit conversion is no longer configured. Update the draft before finalizing."),{status:409});
    for(const line of lines.rows)await c.query("UPDATE sales_invoice_items SET conversion_factor_to_base=$2 WHERE id=$1",[line.id,line.factor]);
    // Serialize competing sales and lock existing balance rows in stable order. The stock movement trigger remains the final no-oversell guard.
    const products=[...new Set(lines.rows.map(x=>String(x.product_id)))].sort((a,b)=>BigInt(a)<BigInt(b)?-1:1);for(const pid of products)await c.query("SELECT pg_advisory_xact_lock(hashtextextended($1,0))",[`${inv.store_id}:${pid}`]);
    await c.query("SELECT product_id FROM inventory_balances WHERE store_id=$1 AND product_id=ANY($2::bigint[]) ORDER BY product_id FOR UPDATE",[inv.store_id,products]);
    const insufficient=await c.query(`WITH requested AS(SELECT product_id,sum(quantity*factor)::numeric(24,8) quantity FROM (
      SELECT li.product_id,li.quantity,CASE WHEN p.base_unit_id=li.unit_id THEN 1::numeric ELSE conv.factor_to_base END factor FROM sales_invoice_items li JOIN products p ON p.id=li.product_id
      LEFT JOIN product_unit_conversions conv ON conv.product_id=p.id AND conv.unit_id=li.unit_id WHERE li.sales_invoice_id=$1) q GROUP BY product_id)
      SELECT r.product_id FROM requested r LEFT JOIN inventory_balances b ON b.store_id=$2 AND b.product_id=r.product_id WHERE COALESCE(b.quantity,0)<r.quantity LIMIT 1`,[id,inv.store_id]);
    if(insufficient.rowCount)throw Object.assign(new Error(`Insufficient stock for product ${insufficient.rows[0].product_id}`),{status:409,code:"INSUFFICIENT_STOCK",productId:insufficient.rows[0].product_id,field:"items"});
    const date=String(inv.invoice_date).slice(0,10),series=inv.series,range=invoicePeriodRange(date,inv.invoice_numbering_period);
    const historicalMax=await c.query(`SELECT COALESCE(max((regexp_match(invoice_number,'([0-9]{1,18})$'))[1]::bigint),0)+1 AS next_number
      FROM sales_invoices WHERE store_id=$1 AND series=$2 AND status<>'draft' AND invoice_number IS NOT NULL
      AND ($3::date IS NULL OR invoice_date >= $3::date) AND ($4::date IS NULL OR invoice_date < $4::date)`,[inv.store_id,series,range.start,range.end]);
    const invoiceNo=await allocateInvoiceNumber(c,{storeId:inv.store_id,documentType:"sale",series,date,policy:inv.invoice_numbering_period,padding:inv.invoice_number_padding,initialNumber:historicalMax.rows[0].next_number});
    await c.query("UPDATE sales_invoices SET invoice_number=$2,salesperson_name_snapshot=$3,status='posted',posted_at=now(),updated_at=now() WHERE id=$1",[id,invoiceNo,req.user.name]);
    if(Number(amount)>0){const key=String(req.body.payment.idempotencyKey);const pm=await c.query("INSERT INTO payments(store_id,payment_number,direction,status,payment_method,amount,payment_date,reference,notes,created_by,customer_id,customer_request_key,dealer_order_id) VALUES($1,$2,'in','posted',$3,$4,current_date,$5,$6,$7,$8,$9,$10) RETURNING id",[inv.store_id,`RCPT-${randomUUID()}`,method,amount,String(req.body.payment.reference||"").slice(0,120)||null,String(req.body.payment.notes||"").slice(0,2000)||null,req.user.id,inv.customer_id,key,dealerOrder?.id||null]);await c.query("INSERT INTO payment_allocations(payment_id,store_id,direction,sales_invoice_id,amount) VALUES($1,$2,'in',$3,$4)",[pm.rows[0].id,inv.store_id,id,amount]);}
    if(dealerOrder){let remaining=(await c.query('SELECT total FROM sales_invoices WHERE id=$1',[id])).rows[0].total;const advances=await c.query(`SELECT p.id,p.amount,COALESCE((SELECT sum(pa.amount) FROM payment_allocations pa WHERE pa.payment_id=p.id AND pa.direction='in'),0)::numeric(18,2) AS allocated FROM payments p WHERE p.dealer_order_id=$1 AND p.status='posted' ORDER BY p.payment_date,p.id FOR UPDATE OF p`,[dealerOrder.id]);for(const advance of advances.rows){const available=(await c.query('SELECT GREATEST($1::numeric-$2::numeric,0)::numeric(18,2) AS amount',[advance.amount,advance.allocated])).rows[0].amount;const allocation=(await c.query('SELECT LEAST($1::numeric,$2::numeric)::numeric(18,2) AS amount',[available,remaining])).rows[0].amount;if(Number(allocation)>0){await c.query(`INSERT INTO payment_allocations(payment_id,store_id,direction,sales_invoice_id,amount) VALUES($1,$2,'in',$3,$4)`,[advance.id,inv.store_id,id,allocation]);remaining=(await c.query('SELECT GREATEST($1::numeric-$2::numeric,0)::numeric(18,2) AS amount',[remaining,allocation])).rows[0].amount;}}const paid=await c.query(`SELECT COALESCE(sum(pa.amount),0)::numeric(18,2) amount FROM payment_allocations pa JOIN payments py ON py.id=pa.payment_id WHERE pa.sales_invoice_id=$1 AND pa.direction='in' AND py.status='posted'`,[id]);await c.query(`UPDATE dealer_orders SET payment_status=CASE WHEN $2::numeric=0 THEN 'UNPAID' WHEN $2::numeric>=$3::numeric THEN 'PAID' ELSE 'PARTIALLY_PAID' END,updated_at=now() WHERE id=$1`,[dealerOrder.id,paid.rows[0].amount,(await c.query('SELECT total FROM sales_invoices WHERE id=$1',[id])).rows[0].total]);await c.query(`INSERT INTO dealer_order_messages(order_id,message_type,body,metadata,created_by) VALUES($1,'INVOICE_FINALIZED',$2,$3,$4)`,[dealerOrder.id,'Sales invoice finalized; verified dealer advances were allocated to the invoice.',{salesInvoiceId:id},req.user.id]);await c.query(`INSERT INTO dealer_order_notifications(order_id,user_id,event_type) SELECT $1,user_id,'INVOICE_FINALIZED' FROM dealer_profiles WHERE id=$2`,[dealerOrder.id,dealerOrder.dealer_id]);await c.query(`INSERT INTO audit_logs(store_id,user_id,action,entity_type,entity_id,after_data) VALUES($1,$2,'dealer.order.invoice_finalized','dealer_order',$3,$4)`,[inv.store_id,req.user.id,dealerOrder.id,{salesInvoiceId:id}]);}
    await processSalesInvoiceBonus(c,id,req.user.id);
    await c.query("INSERT INTO audit_logs(store_id,user_id,action,entity_type,entity_id) VALUES($1,$2,'sales.invoice.finalized','sales_invoice',$3)",[inv.store_id,req.user.id,id]);const invoice=await loadInvoice(id,c);await c.query("COMMIT");return res.json(invoice);
  }catch(e){await c.query("ROLLBACK").catch(()=>{});return dbError(res,e,"Unable to finalize invoice");}finally{c.release();}
}
async function updateSalesStatus(req,res,status){if(!idOk(req.params.id))return res.status(400).json({message:"Invalid invoice ID"});const c=await connection.connect();try{await c.query("BEGIN");const r=await c.query("SELECT * FROM sales_invoices WHERE id=$1 FOR UPDATE",[req.params.id]);if(!r.rowCount)throw Object.assign(new Error("Invoice not found"),{status:404});const inv=r.rows[0];if(!await permitted(req,res,inv.store_id)){await c.query("ROLLBACK");return;}if(status==="cancelled"&&inv.status!=="draft")throw Object.assign(new Error("Only drafts can be cancelled"),{status:409});if(status==="reversed"){if(!await canManageStore(req.user,inv.store_id,["owner","manager"],c)){await c.query("ROLLBACK");return res.status(403).json({message:"Manager authorization is required to reverse a posted sales invoice"});}if(inv.status!=="posted")throw Object.assign(new Error("Only posted invoices can be reversed"),{status:409});const dep=await c.query("SELECT EXISTS(SELECT 1 FROM payment_allocations pa JOIN payments p ON p.id=pa.payment_id WHERE pa.sales_invoice_id=$1 AND p.status='posted') AS paid,(EXISTS(SELECT 1 FROM sales_returns WHERE sales_invoice_id=$1 AND status='posted') OR EXISTS(SELECT 1 FROM sales_return_items ri JOIN sales_returns r ON r.id=ri.sales_return_id JOIN sales_invoice_items si ON si.id=ri.sales_invoice_item_id WHERE si.sales_invoice_id=$1 AND r.status='posted') OR EXISTS(SELECT 1 FROM sales_invoice_return_credits WHERE sales_invoice_id=$1 AND status='posted')) AS returned",[inv.id]);if(dep.rows[0].paid||dep.rows[0].returned)throw Object.assign(new Error("Reverse related payments and returns before reversing this invoice"),{status:409});}
  await c.query("UPDATE sales_invoices SET status=$2,updated_at=now() WHERE id=$1",[inv.id,status]);if(status==="reversed")await reverseInvoiceBonus(c,inv.id,req.user.id,inv.store_id);await c.query("INSERT INTO audit_logs(store_id,user_id,action,entity_type,entity_id) VALUES($1,$2,$3,'sales_invoice',$4)",[inv.store_id,req.user.id,`sales.invoice.${status}`,inv.id]);await c.query("COMMIT");return res.json(await loadInvoice(inv.id));
  }catch(e){await c.query("ROLLBACK").catch(()=>{});return dbError(res,e,"Unable to change invoice status");}finally{c.release();}}
export const cancelSales=(req,res)=>updateSalesStatus(req,res,"cancelled");
export const reverseSales=(req,res)=>updateSalesStatus(req,res,"reversed");
export async function recordSalesPayment(req,res){
  const id=req.params.id,amount=decimal(req.body?.amount,"Payment amount",{scale:2}),key=String(req.body?.idempotencyKey||"");if(amount.includes(" must be a valid ")||Number(amount)<=0)return res.status(400).json({message:"Enter a valid positive payment amount"});if(key.length<8||key.length>120)return res.status(400).json({message:"A payment idempotency key is required"});
  const c=await connection.connect();try{await c.query("BEGIN");const r=await c.query("SELECT * FROM sales_invoices WHERE id=$1 FOR UPDATE",[id]);if(!r.rowCount)throw Object.assign(new Error("Invoice not found"),{status:404});const inv=r.rows[0];if(!await permitted(req,res,inv.store_id)){await c.query("ROLLBACK");return;}const prior=await c.query("SELECT id,store_id,customer_id,amount,payment_method,status FROM payments WHERE customer_request_key=$1 FOR UPDATE",[key]);if(prior.rowCount){const prev=prior.rows[0],numericSame=await c.query("SELECT $1::numeric=$2::numeric AS yes",[prev.amount,amount]),allocation=await c.query("SELECT 1 FROM payment_allocations WHERE payment_id=$1 AND sales_invoice_id=$2",[prev.id,id]);const same=String(prev.store_id)===String(inv.store_id)&&String(prev.customer_id||"")===String(inv.customer_id||"")&&numericSame.rows[0].yes&&prev.payment_method===(req.body.method||"cash")&&prev.status==="posted"&&allocation.rowCount>0;if(!same)throw Object.assign(new Error("Payment request key was already used with different details"),{status:409});await c.query("COMMIT");return res.json(await loadInvoice(id));}if(inv.status!=="posted")throw Object.assign(new Error("Payments require a finalized invoice"),{status:409});const paid=await c.query("SELECT COALESCE(sum(pa.amount),0) amount FROM payment_allocations pa JOIN payments p ON p.id=pa.payment_id WHERE pa.sales_invoice_id=$1 AND p.status='posted'",[id]);const credit=await c.query("SELECT COALESCE(sum(total),0) amount FROM sales_invoice_return_credits WHERE sales_invoice_id=$1 AND status='posted'",[id]);const exceeds=await c.query("SELECT $1::numeric+$2::numeric+$4::numeric>$3::numeric AS yes",[paid.rows[0].amount,amount,inv.total,credit.rows[0].amount]);if(exceeds.rows[0].yes)throw Object.assign(new Error("Payment exceeds the outstanding balance"),{status:409});
  const method=req.body.method||"cash";const configured=await c.query("SELECT 1 FROM payment_method_options WHERE code=$1 AND is_active=TRUE",[method]);if(!configured.rowCount)throw Object.assign(new Error("Payment method is not configured or active"),{status:400});const p=await c.query("INSERT INTO payments(store_id,payment_number,direction,status,payment_method,amount,payment_date,reference,created_by,customer_id,customer_request_key,dealer_order_id) VALUES($1,$2,'in','posted',$3,$4,COALESCE($5::date,current_date),$6,$7,$8,$9,$10) RETURNING id",[inv.store_id,`RCPT-${randomUUID()}`,method,amount,req.body.paymentDate||null,String(req.body.reference||"").slice(0,120)||null,req.user.id,inv.customer_id,key,inv.dealer_order_id||null]);await c.query("INSERT INTO payment_allocations(payment_id,store_id,direction,sales_invoice_id,amount) VALUES($1,$2,'in',$3,$4)",[p.rows[0].id,inv.store_id,id,amount]);if(inv.dealer_order_id){const totalPaid=await c.query(`SELECT COALESCE(sum(pa.amount),0)::numeric(18,2) amount FROM payment_allocations pa JOIN payments py ON py.id=pa.payment_id WHERE pa.sales_invoice_id=$1 AND py.status='posted' AND pa.direction='in'`,[id]);await c.query(`UPDATE dealer_orders SET payment_status=CASE WHEN $2::numeric>=$3::numeric THEN 'PAID' WHEN $2::numeric>0 THEN 'PARTIALLY_PAID' ELSE 'UNPAID' END,updated_at=now() WHERE id=$1`,[inv.dealer_order_id,totalPaid.rows[0].amount,inv.total]);}await processSalesInvoiceBonus(c,id,req.user.id);await c.query("INSERT INTO audit_logs(store_id,user_id,action,entity_type,entity_id) VALUES($1,$2,'sales.payment.recorded','sales_invoice',$3)",[inv.store_id,req.user.id,id]);await c.query("COMMIT");return res.json(await loadInvoice(id));
  }catch(e){await c.query("ROLLBACK").catch(()=>{});return dbError(res,e,"Unable to record payment");}finally{c.release();}
}
